function vaultAccount(operations) {
  const history = [], results = [];
  const total = () => history.reduce((sum, x) => sum + x, 0);
  for (const op of operations) {
    if (op[0] === 'deposit') history.push(op[1]);
    else if (op[0] === 'withdraw') {
      const ok = total() >= op[1];
      if (ok) history.push(-op[1]);
      results.push(ok);
    } else results.push(total());
  }
  return results;
}

class Vault {
  #balance = 0;
  deposit(amount) { this.#balance += amount; }
  withdraw(amount) {
    if (amount > this.#balance) return false;
    this.#balance -= amount;
    return true;
  }
  balance() { return this.#balance; }
}

function vaultAccount(operations) {
  const vault = new Vault(), results = [];
  for (const [name, amount] of operations) {
    if (name === 'deposit') vault.deposit(amount);
    else if (name === 'withdraw') results.push(vault.withdraw(amount));
    else results.push(vault.balance());
  }
  return results;
}
